PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE firs (
    id TEXT PRIMARY KEY,
    name TEXT,
    risk_level TEXT -- e.g., 'HIGH', 'MED', 'LOW'
, lat REAL, lon REAL, geometry TEXT);
CREATE TABLE tafs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    station TEXT NOT NULL,
    raw_text TEXT,
    issue_time DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE test_users (id INTEGER PRIMARY KEY, name TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE flights (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        callsign TEXT NOT NULL,
        ac_type TEXT,
        dep TEXT NOT NULL,
        dest TEXT NOT NULL,
        route TEXT,
        etd DATETIME,
        eta DATETIME,
        status TEXT,
        remarks TEXT,
        alt TEXT,
        taf_dep TEXT,
        taf_arr TEXT,
        enr1 TEXT,
        enr2 TEXT,
        enr3 TEXT,
        cgo TEXT,
        atc TEXT,
        dof TEXT,
        active_route_id TEXT,
        last_updated DATETIME DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(callsign, dof) -- Flight number + Date combination should be unique
      );
CREATE TABLE airport_firs (
    airport_icao TEXT NOT NULL,
    fir_code TEXT NOT NULL,
    PRIMARY KEY (airport_icao, fir_code)
);
CREATE TABLE aircraft (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    registration TEXT UNIQUE NOT NULL,
    ac_type TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE routes (
    id TEXT PRIMARY KEY,
    dep_airport TEXT NOT NULL,
    arr_airport TEXT NOT NULL,
    dep_rwy TEXT,
    sid TEXT,
    waypoint_seq TEXT,
    star TEXT,
    arr_rwy TEXT,
    route_string TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE latlong (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    route_id TEXT,
    waypoint TEXT,
    latitude TEXT,
    longitude TEXT
);
CREATE TABLE notams (
    id TEXT PRIMARY KEY,
    location TEXT NOT NULL,
    q_code TEXT,
    notam_code TEXT,
    message TEXT NOT NULL,
    valid_from DATETIME,
    valid_to DATETIME,
    risk_level TEXT,
    is_active BOOLEAN DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, updated_at DATETIME, kind TEXT DEFAULT 'AD');
CREATE TABLE briefing_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    flights_key TEXT NOT NULL,
    flights TEXT,
    content_json TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE meta (
    key TEXT PRIMARY KEY,
    value TEXT
);
CREATE TABLE airport_notes (icao_code TEXT, day_range TEXT, start_time TEXT, end_time TEXT, note_text TEXT, type TEXT);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_latlong_route ON latlong(route_id);
CREATE UNIQUE INDEX idx_tafs_station ON tafs(station);
CREATE INDEX idx_briefing_reports_flights_key ON briefing_reports(flights_key);
CREATE INDEX idx_notams_location ON notams(location);
CREATE INDEX idx_notams_dates ON notams(valid_from, valid_to);
CREATE INDEX idx_notams_updated_at ON notams(updated_at);
